import sqlite3
import json
import sys

db_path = "/workspace/world.db"
try:
    conn = sqlite3.connect(db_path)
    cur = conn.execute("SELECT cellular_service FROM ts_device_settings LIMIT 1")
    row = cur.fetchone()
    if row is None:
        out = {"error": "no row"}
    else:
        current = row[0]
        out = {"before": current}
        if current == 0:
            conn.execute("UPDATE ts_device_settings SET cellular_service = 1")
            conn.commit()
            out["action"] = "turned_on"
        else:
            out["action"] = "already_on"
        cur2 = conn.execute("SELECT cellular_service FROM ts_device_settings LIMIT 1")
        out["after"] = cur2.fetchone()[0]
    conn.close()
except Exception as e:
    out = {"error": str(e)}

with open("/workspace/cell_out.txt", "w") as f:
    f.write(json.dumps(out))
